import streamDeck, { action, type DialRotateEvent } from "@elgato/streamdeck";

import { store } from "../plugin.ts";
import { metricFace, type DeckState, type Face, type MetricField } from "../state.ts";
import { RunlogAction } from "./base.ts";

export type MetricSettings = { field?: MetricField };

/** The fields a dial cycles through. A counter or resource is the run's own and is not on this wheel. */
const FIELDS = ["score", "unit", "clock", "latest", "leader"] as const;

/** The field a dial's rotation lands on, wrapping both ways. */
export function nextField(field: MetricField, by: number): MetricField {
  const i = typeof field === "string" ? FIELDS.indexOf(field) : -1;
  return FIELDS[(i + by + FIELDS.length) % FIELDS.length]!;
}

/** A number from the run: the score, the unit, a clock, the last result, the leader. */
@action({ UUID: "com.scrthq.runlog.metric" })
export class Metric extends RunlogAction<MetricSettings> {
  face(state: DeckState, settings: MetricSettings, now: number): Face {
    return settings.field ? metricFace(state, settings.field, now) : { title: "Set up", tone: "dim" };
  }

  /** Rotating a dial steps its field and redraws at once. */
  override async onDialRotate(ev: DialRotateEvent<MetricSettings>): Promise<void> {
    const field = nextField(ev.payload.settings.field ?? "score", Math.sign(ev.payload.ticks));
    await ev.action.setSettings({ field });
    await this.draw(ev.action, { field });
  }

  /** The fixed fields are known to the inspector; the counters and resources are the run's own. */
  override async onPropertyInspectorDidAppear(): Promise<void> {
    await super.onPropertyInspectorDidAppear();
    const snap = store.state.snapshot;
    await streamDeck.ui.sendToPropertyInspector({
      t: "fields",
      counters: snap?.counters?.map((c) => ({ id: c.id, label: c.label })) ?? [],
      resources: snap?.resources?.map((r) => ({ id: r.id, label: r.label })) ?? [],
    });
  }
}
=== streamdeck/src/plugin.ts ===
import streamDeck from "@elgato/streamdeck";

import { Connect } from "./actions/connect.ts";
import { Metric } from "./actions/metric.ts";
import { Next } from "./actions/next.ts";
import { Press } from "./actions/press.ts";
import { pin, Run, runsForInspector } from "./actions/run.ts";
import { Undo } from "./actions/undo.ts";
import { loadSession, normalizeBase, signIn, signOut, type Account } from "./session.ts";
import { openWire } from "./socket.ts";
import { makeStore } from "./store.ts";
import { idleDeadline, type DeckState } from "./state.ts";

/** Where Runlog lives when the streamer has not said otherwise. */
const DEFAULT_API = "https://runlog.scrthq.com";

/**
 * What the plugin keeps between launches.
 *
 * The address and the pinned run, and nothing else: global settings are
 * handed to the property inspector, which is a web view, so the session
 * never comes near them. It lives in a file of the plugin's own.
 */
type Globals = { apiBase?: string; pinned?: string | null };

let apiBase = DEFAULT_API;

export const store = makeStore();
export const wire = openWire((): Account => ({ apiBase }), store);

/**
 * The profile a deck is switched to once a run attaches.
 *
 * Not wired into the manifest yet: `streamdeck validate` refuses a
 * `Profiles` entry without the `.streamDeckProfile` file behind it, and
 * that file can only come from exporting the laid-out profile in the
 * Stream Deck app. Once `profiles/Runlog.streamDeckProfile` exists, the
 * manifest gains `Profiles: [{ Name: "Runlog", DeviceType: 0, Readonly: false, DontAutoSwitchWhenInstalled: true }]`.
 * Until then the switch below fails quietly, which is correct for a copy
 * without the profile.
 */
const PROFILE_NAME = "Runlog";

/**
 * Attaching switches the deck to the Runlog profile. It is the one
 * attach feedback that works on every model, a six-key Mini included,
 * and it puts the run's keys under the streamer's hand the moment a run
 * starts. Only on a change from nothing to something: a snapshot landing
 * is not a reason to yank the deck away from whatever it was showing.
 */
let wasAttached: string | null = null;
store.subscribe((s) => {
  if (s.attached && !wasAttached)
    for (const d of streamDeck.devices) void streamDeck.profiles.switchToProfile(d.id, PROFILE_NAME).catch(() => {});
  wasAttached = s.attached;
});

// The Run inspector's list is only as fresh as the last appear; a run
// starting or ending while the picker is open moves it without the
// streamer closing and reopening the page.
let lastRuns: DeckState["runs"] | null = null;
store.subscribe((s) => {
  if (s.runs === lastRuns) return;
  lastRuns = s.runs;
  if (streamDeck.ui.action) void streamDeck.ui.sendToPropertyInspector({ t: "runs", runs: runsForInspector(s.runs), pinned: s.pinned });
});

/**
 * Switching the deck on.
 *
 * The address is read again first, so the one the streamer last typed is the
 * one dialed. Reconnecting through drops after that is the wire's own job.
 */
export function turnOn(): void {
  if (store.state.on) return;
  store.dispatch({ t: "on", on: true });
  void (async () => {
    await readGlobals();
    streamDeck.logger.info("on: connecting");
    wire.connect();
  })();
}

/** Switching it off, by a press or - with `idle` - by the deck's own timer. */
export function turnOff(idle = false): void {
  wire.disconnect();
  store.dispatch({ t: "on", on: false, idle });
  streamDeck.logger.info(idle ? "off: idle for thirty minutes" : "off: by request");
}

/** Tells whichever inspector is open where it is pointed and whether anyone is signed in. */
export async function sayWho(): Promise<void> {
  await streamDeck.ui.sendToPropertyInspector({ t: "who", signedIn: loadSession() !== null, apiBase });
}

function applyGlobals(g: Globals): void {
  apiBase = normalizeBase(g.apiBase ?? "") || DEFAULT_API;
  // Only on a change: this fires from the plugin's own write of a pin as
  // much as from another surface's, and a pin already applied locally
  // should not force the run's snapshot to reload for nothing.
  if (g.pinned !== undefined && g.pinned !== store.state.pinned) store.dispatch({ t: "pin", id: g.pinned });
}

async function readGlobals(): Promise<void> {
  applyGlobals(await streamDeck.settings.getGlobalSettings<Globals>());
}

// A deck holding no run for half an hour closes its own socket rather than
// sitting on one all night. A deck following a run never times out.
let idleSince: number | null = null;
let idleTimer: ReturnType<typeof setTimeout> | null = null;
store.subscribe((state) => {
  const now = Date.now();
  const deadline = idleDeadline(state, idleSince ?? now);
  if (deadline === null) {
    idleSince = null;
    if (idleTimer) clearTimeout(idleTimer);
    idleTimer = null;
    return;
  }
  if (idleTimer) return;
  idleSince = now;
  idleTimer = setTimeout(() => {
    idleTimer = null;
    turnOff(true);
  }, deadline - now);
});

/** The device flow's two lines, as the inspector needs them: the page and the code. */
function codeFromLines(): (line: string) => void {
  let code: string | null = null;
  let url: string | null = null;
  return (line) => {
    code = /^ {2}Code {2}(\S.*)$/.exec(line)?.[1]?.trim() ?? code;
    url = /^ {2}Open {2}(\S+)$/.exec(line)?.[1] ?? url;
    if (code && url) void streamDeck.ui.sendToPropertyInspector({ t: "code", code, url });
  };
}

streamDeck.ui.onSendToPlugin<{ t?: string; id?: string | null }>(async (ev) => {
  switch (ev.payload?.t) {
    case "pin":
      await pin(ev.payload?.id ?? null);
      break;
    case "signin":
      try {
        streamDeck.logger.info("sign-in: starting the device flow");
        await signIn({ apiBase }, codeFromLines(), () => {});
        store.dispatch({ t: "session", state: "ok" });
        streamDeck.logger.info("sign-in: done");
        // Signed in is not connected: the streamer presses Connect.
        await streamDeck.ui.sendToPropertyInspector({ t: "who", name: "you", signedIn: true, apiBase });
      } catch (e) {
        // The reason goes back to the inspector, not only to the log: the
        // streamer is looking at the button they pressed, and a status line
        // that flips back to "Not signed in" tells them nothing.
        const error = e instanceof Error ? e.message : "unknown";
        streamDeck.logger.error(`sign-in: failed (${error})`);
        await streamDeck.ui.sendToPropertyInspector({ t: "who", signedIn: false, apiBase, error });
      }
      break;
    case "signout":
      turnOff();
      signOut();
      store.dispatch({ t: "session", state: "none" });
      streamDeck.logger.info("signed out");
      await streamDeck.ui.sendToPropertyInspector({ t: "who", signedIn: false, apiBase });
      break;
    case "reconnect":
      turnOff();
      turnOn();
      break;
    default:
      break;
  }
});

streamDeck.logger.setLevel("info");
streamDeck.settings.onDidReceiveGlobalSettings<Globals>((ev) => applyGlobals(ev.settings));

// A flash lasts three seconds and nothing else clears it; the tick is what
// puts a refused key back to what it was saying.
setInterval(() => store.dispatch({ t: "tick" }), 1000);

for (const a of [new Next(), new Press(), new Undo(), new Run(), new Metric(), new Connect()]) {
  streamDeck.actions.registerAction(a);
}

void streamDeck.connect().then(async () => {
  // Launch is quiet: the settings, the session, and nothing else. No socket
  // and no token refresh until the streamer presses Connect.
  await readGlobals();
  const signedIn = loadSession() !== null;
  store.dispatch({ t: "session", state: signedIn ? "ok" : "none" });
  streamDeck.logger.info(`launched: ${signedIn ? "signed in" : "not signed in"}, not connected`);
});

